section.para:
WebDyne can be incorporated into a traditional app.psgi startup file for PSGI in the following form. In this example any file with a .psp extension is routed to WebDyne for
      rendering

            PSGI Application Startup



#  Save as app.psgi
#
use strict;
use warnings;
use Plack::Builder;
use WebDyne::PSGI;

my $home_app = sub {
    return [
        200,
        [ 'Content-Type' => 'text/plain' ],
        [ "Welcome to the Home Page\n" ]
    ];
};

my $webdyne_app = WebDyne::PSGI->new(
    root  => '.',
    index => 1,
)->to_app;

builder {
    sub {
        my $env = shift;
        # Serve any URL ending in .psp through WebDyne
        if ($env->{PATH_INFO} =~ /\.psp$/i) {
            return $webdyne_app->($env);
        }

        return $home_app->($env);
    };
};
Save as app.psgi and start with command line:#  Assuming app.psgi in current directory
#
plackup


#  Or if named differently
#
plackup myapp.psgi

Or you can mount all files from a particular directory against the WebDyne render engine.

            PSGI Mount Startup



use strict;
use warnings;
use Plack::Builder;
use WebDyne::PSGI;

# Main app for /
my $home_app = sub {
    return [
        200,
        [ 'Content-Type' => 'text/plain' ],
        [ "Welcome to the Home Page\n" ]
    ];
};

# Mount everything using builder
builder {
    mount '/'         => $home_app;
    mount '/webdyne'  => WebDyne::PSGI->new( root => '.')->to_app;
};

WebDyne can be incorporated into a traditional app.pagi/app.pl startup file for PAGI in the following form. In this example any file with a .psp extension is routed to WebDyne for
      rendering:

            PAGI Application Startup



use strict;
use warnings;
use Future::AsyncAwait;
use experimental 'signatures';

use PAGI::Middleware::Builder;
use WebDyne::PAGI;

my $home_app = async sub ($scope, $receive, $send) {
    die "Unsupported scope type: $scope->{type}"
        unless $scope->{type} eq 'http';

    await $send->({
        type    => 'http.response.start',
        status  => 200,
        headers => [
            [ 'content-type', 'text/plain' ],
        ],
    });

    await $send->({
        type => 'http.response.body',
        body => "Welcome to the Home Page\n",
        more => 0,
    });
};

my $webdyne_app = WebDyne::PAGI->new(
    root  => '.',
)->to_app;

builder {
    async sub ($scope, $receive, $send) {
        if (($scope->{path} // '') =~ /\.psp$/i) {
            return await $webdyne_app->($scope, $receive, $send);
        }

        return await $home_app->($scope, $receive, $send);
    };
};

para.programlisting:
#  Works
#
sub greeting { print "Hello World" }


#  Is the same as
#
sub greeting { return "Hello World" }
sub greeting { my $var="Hello World"; return $var }


# But best is
#
sub greeting { my $var="Hello World"; return \$var }


# If you don't want to display anything return \undef,
#
sub greeting { return \undef }

section.screen:
$_={
    'WebDyne::Constant' => {

        #  Inserted as <meta> into <head> section
        #
        WEBDYNE_META => {
            #  These all rendered as <meta name="$key" content="$value">
            viewport => 'width=device-width, initial-scale=1.0',
            author => 'Bob Foobar',
            #  This one rendered as <meta http-equiv="X-UA-Compatible" content="IE=edge">
            'http-equiv=X-UA-Compatible' => 'IE=edge',
            'http-equiv=refresh' => '5; url=https://www.example.com'
        }

        #  This is inserted inside the <html> starting tag, works for <start_html> or straight <html>
        #
        WEBDYNE_HTML_PARAM => {
            lang => 'de'
        }

        #  This is inserted before the </head> closing tag, works for <start_html> or straight <html>
        #
        WEBDYNE_HEAD_INSERT => << 'END'
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@picocss/pico@2/css/pico.classless.min.css">
<style>
:root { --pico-font-size: 85% }
body { padding-top: 10px; padding-left: 10px;
</style>
END

    }
}

para.programlisting:
__PERL__


#  Good
#
sub hello {

    return err('no foobar') if !$foobar;

}

# Also OK
#
sub hello {

    return die('no foobar') if !$foobar;

}

section.para:
When running Perl code within a WebDyne page the very first parameter passed to any routine (in-line or in a __PERL__ block) is an instance of the WebDyne page object (referred to
      as $self in most of the examples, e.g. $self->print("Hello World")). All methods return undef on failure, and raise an error
      using the err() function. The following methods are available to any instance of the WebDyne object:

section.programlisting:
# sample /etc/webdyne.conf.pl file
#
$VAR1={
        WebDyne::Constant => {

                WEBDYNE_CACHE_DN       => '/data1/webdyne/cache',
                WEBDYNE_STORE_COMMENTS => 1,
                #  ... more variables for WebDyne package

       },

       WebDyne::Session::Constant => {

                WEBDYNE_SESSION_ID_COOKIE_NAME => 'session_cookie',
                #  ... more variables for WebDyne::Session package

       },

};

# Setting more complex variables

PerlHandler     WebDyne
<Perl>
$WebDyne::Constant::WEBDYNE_CACHE_DN='/data1/webdyne/cache';
$WebDyne::Constant::WEBDYNE_STORE_COMMENTS=1;
$WebDyne::Session::Constant::WEBDYNE_SESSION_ID_COOKIE_NAME='session_cookie';
</Perl>

para.programlisting:
use WebDyne;
use WebDyne::Constant;

#  Error display/extended display on/off. More granular options below.
#  Set to 1 to enable, 0 to disable
#
$WebDyne::WEBDYNE_ERROR_SHOW=1;
$WebDyne::WEBDYNE_ERROR_SHOW_EXTENDED=1;

#  Extended error control.
#
#  $WebDyne::WEBDYNE_ERROR_SOURCE_CONTEXT_SHOW=1;
#  $WebDyne::WEBDYNE_ERROR_SOURCE_CONTEXT_LINES_PRE=4;
#  $WebDyne::WEBDYNE_ERROR_SOURCE_CONTEXT_LINES_POST=4;

listitem.para:
Any HTML you want inserted before the closing </head> tag, e.g. stylesheet or script includes to be added to every PSP page. Must be
              valid HTML <head> directives, not interpreted or compiled by WebDyne, incorporated as-is. By default WebDyne inlines its bundled webdyne.css stylesheet;
              set this item to undef to disable default stylesheet insertion.

section.programlisting:
#  Debug the internal perl routine in WebDyne
#
$ WEBDYNE_DEBUG=perl perl -Ilib bin/wdrender time.psp
